    ld.param.u64    %rd1, [input_ptr];
    ld.param.u64    %rd2, [output_ptr];

    // -----------------------------------------------------------------
    // Thread identifiers (1‑D grid & block)
    // -----------------------------------------------------------------
    mov.u32 %r1, %ctaid.x;          // blockIdx.x
    mov.u32 %r2, %ntid.x;           // blockDim.x
    mov.u32 %r3, %tid.x;            // threadIdx.x
    mad.lo.u32 %r4, %r1, %r2, %r3;  // global thread id

    // -----------------------------------------------------------------
    // Compile‑time constants (hard‑coded for the reference model)
    // -----------------------------------------------------------------
    .set CONST_BATCH, 128
    .set CONST_DIM1, 4096
    .set CONST_DIM2, 4095
    .set TOTAL_OUT, 524160        // 128 * 4095

    // -----------------------------------------------------------------
    // Bounds check: if tid >= total output elements, exit
    // -----------------------------------------------------------------
    setp.ge.u32 %p1, %r4, TOTAL_OUT;
    @%p1 ret;

    // -----------------------------------------------------------------
    // Derive output coordinates:
    //   b = tid / DIM2   (batch index)
    //   j = tid % DIM2   (dim2 index)
    // -----------------------------------------------------------------
    div.u32 %r5, %r4, CONST_DIM2;   // b
    rem.u32 %r6, %r4, CONST_DIM2;   // j

    // -----------------------------------------------------------------
    // Accumulate sum over i = 0 .. DIM1-1
    // -----------------------------------------------------------------
    mov.f32 %f0, 0f0;               // accumulator (float32)
    mov.u32 %r7, 0;                 // i = 0

.Loop_i:
    setp.ge.u32 %p2, %r7, CONST_DIM1;
    @%p2 bra .Lend_i;

    // idx = ((b * DIM1) + i) * DIM2 + j
    mul.lo.u32 %r8, %r5, CONST_DIM1;    // b * DIM1
    add.u32 %r9, %r8, %r7;              // b*DIM1 + i
    mul.lo.u32 %r10, %r9, CONST_DIM2;   // * DIM2
    add.u32 %r11, %r10, %r6;            // + j

