    add.u64 %rd4, %rd1, %rd3;           // address of input element

    ld.global.f16 %h1, [%rd4];
    cvt.f32.f16 %f1, %h1;
    add.f32 %f0, %f0, %f1;              // sum += value

    add.u32 %r7, %r7, 1;                // i++
    bra .Loop_i;

.Lend_i:
    // -----------------------------------------------------------------
    // Compute mean = sum / DIM1  (float32) and cast back to fp16
    // -----------------------------------------------------------------
    mov.f32 %f2, 4096.0;
    div.f32 %f3, %f0, %f2;
    cvt.f16.f32 %h2, %f3;

    // -----------------------------------------------------------------
    // Write result: out_offset = b * DIM2 + j
    // -----------------------------------------------------------------
    mul.lo.u32 %r12, %r5, CONST_DIM2;
    add.u32 %r13, %r12, %r6;
    cvt.u64.u32 %rd5, %r13;
    add.u64 %rd6, %rd2, %rd5;
